def icon(name: str, size: int = 16, label: str | None = None) -> Markup:
    aria = f' role="img" aria-label="{label}"' if label else ' aria-hidden="true"'
    return Markup(
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
        f'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="icon"{aria}>'
        f'{PATHS[name]}</svg>')
